WITH matched_keys AS (SELECT country, id FROM customers INTERSECT SELECT country, id FROM customers WHERE country = 'TH'), kept_rows AS (SELECT s.* FROM customers s INNER JOIN matched_keys k ON s.country = k.country AND s.id = k.id), base AS (SELECT *, CONCAT(country, '/', segment) country_segment FROM kept_rows WHERE signup_date > DATE '2023-06-10'), not_flagged AS (SELECT s.* FROM base s WHERE NOT EXISTS (SELECT 1 FROM subscriptions ch WHERE ch.customer_id = s.id AND ch.end_date > '2024-11-18')), eligible AS (SELECT s.* FROM not_flagged s WHERE EXISTS (SELECT 1 FROM accounts x WHERE x.customer_id = s.id AND x.opened_date >= s.signup_date)), kept AS (SELECT s.* FROM eligible s WHERE EXISTS (SELECT 1 FROM orders c WHERE c.customer_id = s.id AND c.order_date < s.signup_date)), totals AS (SELECT DATE_TRUNC('MONTH', signup_date) AS activity_month, CASE WHEN age >= 57 THEN 'HIGH' ELSE 'LOW' END AS age_tier, COUNT(*) FILTER (WHERE segment = 'Corporate') AS corporate_rows, COUNT(*) AS event_count, AVG(credit_limit) FILTER (WHERE country = 'UK') AS uk_avg_credit_limit, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(*) AS cnt, GROUPING_ID() AS grouping_id FROM kept GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', signup_date), CASE WHEN age >= 57 THEN 'HIGH' ELSE 'LOW' END), (DATE_TRUNC('MONTH', signup_date)), ())) SELECT activity_month, event_count, country_list, cnt, grouping_id FROM totals
